      prefix += hours[i] > 8 ? 1 : -1;
      if (prefix > 0) {
        ans = i + 1;
      } else {
        if (!map.contains(prefix))
          map[prefix] = i;
        if (const auto it = map.find(prefix - 1); it != map.cend())
