      return true;
    if (states[u] == State.VISITED)
      return false;
    states[u] = State.VISITING;
    for (final int v : graph[u]) {
      if (hasCycle(graph, v, states, depth))
        return true;
      depth[u] = Math.max(depth[u], 1 + depth[v]);
    }
    states[u] = State.VISITED;
    return false;
  }
}

